/**
 * What Rock adds to a person's profile card when they show their public profile details: how
 * to reach them and the church's own template. Read as the card opens, never stored by chat.
 */
export type ChatProfileDetailsBag = {
    /**
     * Gets or sets whether the person shows their details to the person asking. False wherever
     * chat would not show this person, and then nothing else is set.
     */
    isShown: boolean;

    /** Gets or sets the person's email address, or null when they have none Rock still sends to. */
    email?: string | null;

    /**
     * Gets or sets the person's mobile phone as Rock formats it for display, or null when they
     * have none or it is unlisted.
     */
    mobilePhone?: string | null;

    /** Gets or sets the tel: address that dials the mobile phone. */
    mobilePhoneUri?: string | null;

    /**
     * Gets or sets the church's profile card template rendered for this person, already made
     * safe to draw, or null when there is no template or it rendered nothing.
     */
    lavaHtml?: string | null;
};
